package com.tesis.urbe.leccion.entity;

import jakarta.persistence.*;

/**
 * Intento de lección guardado en la tabla {@code intento_leccion}: solo
 * usuario + lección (sin sección ni resultado), tal como define el DDL:
 *
 * <pre>
 * create table public.intento_leccion (
 *     id_intento_leccion integer generated by default as identity not null,
 *     idusuario integer not null,
 *     idleccion integer not null,
 *     ...
 * );
 * </pre>
 *
 * <p><b>No confundir</b> con {@link IntentoLeccionEntity}, que mapea la tabla
 * {@code intentoleccion}: esa además guarda {@code idseccion} y
 * {@code escorrecto} y alimenta las estadísticas de tasa de error.
 */
@Entity
@Table(name = "intento_leccion")
public class RegistroIntentoLeccionEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id_intento_leccion")
    private Integer idIntentoLeccion;

    @Column(name = "idusuario", nullable = false)
    private Integer idUsuario;

    @Column(name = "idleccion", nullable = false)
    private Integer idLeccion;

    public RegistroIntentoLeccionEntity() {}

    public RegistroIntentoLeccionEntity(Integer idUsuario, Integer idLeccion) {
        this.idUsuario = idUsuario;
        this.idLeccion = idLeccion;
    }

    public Integer getIdIntentoLeccion() { return idIntentoLeccion; }
    public void setIdIntentoLeccion(Integer idIntentoLeccion) { this.idIntentoLeccion = idIntentoLeccion; }

    public Integer getIdUsuario() { return idUsuario; }
    public void setIdUsuario(Integer idUsuario) { this.idUsuario = idUsuario; }

    public Integer getIdLeccion() { return idLeccion; }
    public void setIdLeccion(Integer idLeccion) { this.idLeccion = idLeccion; }
}
